router.use(require('../middleware/auth').onlyKnownRoutes(router));router.use(authenticate,requireTenant);router.use(requireModule('hrm'));
const ADMIN=['hospital_admin','super_admin'];
const isAdmin=req=>ADMIN.includes(req.user.role);
const fail=(res,message,status=400)=>res.status(status).json({success:false,message});
const clean=(v,n=1000)=>String(v??'').trim().slice(0,n);
const validId=id=>mongoose.isValidObjectId(id);
