function localDateKey(date,tz='Asia/Kolkata'){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const v=Object.fromEntries(parts.map(p=>[p.type,p.value]));return `${v.year}-${v.month}-${v.day}`;}
function dayStart(key){return new Date(`${key}T00:00:00.000Z`);}
function zonedDate(key,time,tz='Asia/Kolkata'){const [y,m,d]=key.split('-').map(Number),[hh,mm]=time.split(':').map(Number);let guess=Date.UTC(y,m-1,d,hh,mm);for(let i=0;i<3;i++){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess));const v=Object.fromEntries(parts.map(p=>[p.type,p.value]));const shown=Date.UTC(+v.year,+v.month-1,+v.day,+v.hour,+v.minute);guess+=Date.UTC(y,m-1,d,hh,mm)-shown;}return new Date(guess);}
function validDateKey(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(value||'')))return false;const d=new Date(`${value}T00:00:00.000Z`);return !Number.isNaN(+d)&&d.toISOString().slice(0,10)===value}
