function parseLocalTime(value,tz='Asia/Kolkata'){if(!value)return undefined;const s=String(value);if(/[zZ]$|[+-]\d{2}:?\d{2}$/.test(s))return new Date(s);const [date,time]=s.split('T');if(!date||!time)return new Date(s);return zonedDate(date,time.slice(0,5),tz);}
function addDaysKey(key,n){const d=new Date(`${key}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function minutesBetween(a,b){return Math.max(0,Math.round((new Date(b)-new Date(a))/60000));}
async function nextNo(tenantId,prefix){const key=`${tenantId}:${prefix}:${new Date().getFullYear()}`;const s=await Sequence.findOneAndUpdate({key},{$inc:{value:1}},{new:true,upsert:true,setDefaultsOnInsert:true});return `${prefix}-${new Date().getFullYear()}-${String(s.value).padStart(5,'0')}`;}
async function getEmployee(req,id){if(!validId(id))return null;const filter={_id:id,tenantId:req.tenantId,...branchScope(req)};if(req.user.role==='employee'){const own=await Employee.findOne({tenantId:req.tenantId,userId:req.user._id}).select('_id');if(!own||String(own._id)!==String(id))return null;}return Employee.findOne(filter);}
async function myEmployee(req){return Employee.findOne({tenantId:req.tenantId,userId:req.user._id,status:{$ne:'archived'}});}
function noSalary(req){return !req.permissions?.includes('*')&&!req.permissions?.includes('employee.salary.view')&&req.user.role!=='hospital_admin';}
function safeEmployee(doc,req){const x=doc?.toObject?doc.toObject():{...doc};if(noSalary(req))delete x.salaryStructureId;if(x.profilePhoto)delete x.profilePhoto.storageKey;return x;}
async function managerCycle(employeeId,managerId,tenantId){let current=managerId,seen=new Set();for(let i=0;current&&i<50;i++){if(String(current)===String(employeeId))return true;if(seen.has(String(current)))return true;seen.add(String(current));const row=await Employee.findOne({_id:current,tenantId}).select('reportingManagerId').lean();current=row?.reportingManagerId;}return false;}
async function validEmployeeRefs(req,b){const branchId=b.branchId||req.branchIds[0];if(!validId(branchId)||!canBranch(req,branchId)||!await Branch.exists({_id:branchId,tenantId:req.tenantId,active:true}))return {error:'Select an active branch you can access'};if(b.departmentId&&!await Department.exists({_id:b.departmentId,tenantId:req.tenantId,active:true,branchIds:branchId}))return {error:'Department is invalid for the selected branch'};if(b.designationId&&!await Designation.exists({_id:b.designationId,tenantId:req.tenantId,active:true,branchIds:branchId}))return {error:'Designation is invalid for the selected branch'};if(b.departmentId&&b.designationId&&!await Designation.exists({_id:b.designationId,tenantId:req.tenantId,departmentId:b.departmentId}))return {error:'Designation does not belong to the selected department'};if(b.reportingManagerId&&!await Employee.exists({_id:b.reportingManagerId,tenantId:req.tenantId,branchId,status:'active'}))return {error:'Reporting manager must be active in the same branch'};if(b.doctorId&&!await Doctor.exists({_id:b.doctorId,tenantId:req.tenantId,branchIds:branchId}))return {error:'Linked doctor must belong to this tenant and branch'};if(b.userId&&!await User.exists({_id:b.userId,tenantId:req.tenantId,active:true,role:'employee',branchIds:branchId}))return {error:'Linked user account is invalid'};return {branchId};}
