function magicValid(file){const b=fs.readFileSync(file.path);if(file.mimetype==='application/pdf')return b.subarray(0,5).toString()==='%PDF-';if(file.mimetype==='image/jpeg')return b[0]===0xff&&b[1]===0xd8&&b[2]===0xff;if(file.mimetype==='image/png')return b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));return false;}
