 if(type==='late'||type==='overtime'){const rows=await Attendance.find({...scope,workDate:{$gte:from,$lte:to},...(type==='late'?{lateMinutes:{$gt:0}}:{overtimeMinutes:{$gt:0}})}).populate('employeeId','employeeNo firstName lastName').lean();return csv(res,`${type}-attendance.csv`,['Employee ID','Employee','Date','Late minutes','Overtime minutes'],rows.map(x=>[x.employeeId?.employeeNo,`${x.employeeId?.firstName||''} ${x.employeeId?.lastName||''}`,x.workDate?.toISOString().slice(0,10),x.lateMinutes,x.overtimeMinutes]));}
 if(type==='salary-register'){if(noSalary(req))return fail(res,'Salary permission required',403);const rows=await PayrollRecord.find({tenantId:req.tenantId,employeeId:{$in:departmentEmployeeIds||await Employee.distinct('_id',scope)},status:{$in:['released','paid']}}).populate('runId','periodStart periodEnd status').lean();return csv(res,'salary-register.csv',['Employee','Employee ID','Period','Gross','Deductions','Net','Status'],rows.map(x=>[x.employeeSnapshot?.name,x.employeeSnapshot?.employeeNo,x.runId?.periodStart?.toISOString().slice(0,10),x.gross,x.deductionTotal,x.net,x.status]));}
 if(type==='appraisals'){const ids=await Employee.distinct('_id',scope);const rows=await PerformanceReview.find({tenantId:req.tenantId,employeeId:{$in:departmentEmployeeIds||ids}}).populate('employeeId','employeeNo firstName lastName').populate('periodId','name').lean();return csv(res,'appraisals.csv',['Employee','Period','Status','Manager feedback'],rows.map(x=>[x.employeeId?.employeeNo,x.periodId?.name,x.status,x.managerFeedback]));}
 if(type==='reimbursements'){const rows=await Expense.find({...scope,...employeeFilter,expenseType:'reimbursement',expenseDate:{$gte:from,$lte:to}}).populate('employeeId','employeeNo firstName lastName').lean();return csv(res,'reimbursements.csv',['Expense','Employee','Date','Amount','Status','Payment reference'],rows.map(x=>[x.expenseNo,x.employeeId?.employeeNo,x.expenseDate?.toISOString().slice(0,10),x.amount,x.status,x.paymentReference]));}
 if(type==='feedback'){const rows=await PatientFeedback.find({...scope,createdAt:{$gte:from,$lte:to}}).populate('patientId','uhid').lean();return csv(res,'patient-feedback.csv',['UHID','Rating','Category','Message','Status'],rows.map(x=>[x.patientId?.uhid,x.rating,x.category,x.message,x.status]));}
 if(type==='notifications'){const rows=await NotificationOutbox.find({...scope,createdAt:{$gte:from,$lte:to}}).lean();return csv(res,'notification-delivery.csv',['Title','Category','Status','Attempts','Delivered channels','Last error','Created'],rows.map(x=>[x.title,x.category,x.status,x.attempts,(x.deliveredChannels||[]).join('; '),x.lastError,x.createdAt?.toISOString()]));}
