router.post('/hrm/notifications/dispatch',requirePermission('notifications.manage'),audit('notification.outbox.dispatched','notification_outbox'),asyncHandler(async(req,res)=>{
 const key=clean(req.get('Idempotency-Key'),160)||clean(req.body.idempotencyKey,160);if(!key)return fail(res,'Idempotency-Key is required');
 const roles=Array.isArray(req.body.roles)?req.body.roles.filter(x=>['hospital_admin','branch_admin','doctor','receptionist','nurse','pharmacist','lab_technician','accountant','employee'].includes(x)):[];const category=clean(req.body.category,40)||'system',channels=req.body.channels||['inApp'];if(!['appointment','prescription','lab_report','invoice','payment','announcement','system','hrm','attendance','leave','payroll','crm','complaint','recruitment'].includes(category))return fail(res,'Unsupported notification category',422);if(!Array.isArray(channels)||!channels.length||channels.some(x=>!['inApp','email','sms','whatsapp'].includes(x)))return fail(res,'Invalid notification channels',422);if(!clean(req.body.title,160)||!clean(req.body.message,1000))return fail(res,'Notification title and message are required',422);
 let recipients=[];
 if(roles.length){recipients=await User.find({tenantId:req.tenantId,active:true,role:{$in:roles},...(isAdmin(req)?(req.body.branchId?{branchIds:req.body.branchId}:{}):{branchIds:{$in:req.branchIds}}),...(req.body.branchId?{branchIds:req.body.branchId}:{})}).select('_id').lean();}
 else if(req.body.userId&&await User.exists({_id:req.body.userId,tenantId:req.tenantId,active:true,...(!isAdmin(req)?{branchIds:{$in:req.branchIds}}:{}),...(req.body.branchId?{branchIds:req.body.branchId}:{})}))recipients=[{_id:req.body.userId}];
 else return fail(res,'Provide an active userId or valid recipient roles',422);
 if(req.body.branchId&&!canBranch(req,req.body.branchId))return fail(res,'Branch access denied',403);
 const results=[];for(const user of recipients){results.push(await enqueue({tenantId:req.tenantId,branchId:req.body.branchId,userId:user._id,category,title:clean(req.body.title,160),message:clean(req.body.message,1000),channels,idempotencyKey:`${key}:${user._id}`,createdBy:req.user._id}));}
 res.status(202).json({success:true,queued:results.length,data:results,message:'Notifications queued; delivery status is available in the outbox'});
}));

